package com.imageproc.pipeline

import java.io.File
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.logging.Logger
import java.util.logging.FileHandler
import java.util.logging.SimpleFormatter

data class ProcessingRequest(
    val imageId: String,
    val userId: String,
    val transformations: List<String>,
    val metadata: Map<String, String>
)

data class RateLimitEntry(
    val count: AtomicInteger = AtomicInteger(0),
    val windowStart: Long = System.currentTimeMillis()
)

class ImageProcessingPipeline(
    private val maxRequestsPerMinute: Int = 60,
    private val maxRetries: Int = 3,
    private val logDir: String = "/var/log/imageproc"
) {
    private val rateLimitMap = ConcurrentHashMap<String, RateLimitEntry>()
    private val logger = Logger.getLogger("ImageProcessingPipeline")
    private val retryDelays = listOf(100L, 500L, 2000L)

    init {
        val handler = FileHandler("$logDir/pipeline.log", true)
        handler.formatter = SimpleFormatter()
        logger.addHandler(handler)
    }

    fun processImage(request: ProcessingRequest): Result<ByteArray> {
        if (!checkRateLimit(request.userId)) {
            logProcessingEvent(request, "RATE_LIMITED")
            return Result.failure(RateLimitException("Rate limit exceeded for user: ${request.userId}"))
        }

        return executeWithRetry(request)
    }

    private fun checkRateLimit(userId: String): Boolean {
        val entry = rateLimitMap.computeIfAbsent(userId) { RateLimitEntry() }
        val now = System.currentTimeMillis()

        if (now - entry.windowStart > 60_000) {
            rateLimitMap[userId] = RateLimitEntry()
            return true
        }

        return entry.count.incrementAndGet() <= maxRequestsPerMinute
    }

    private fun executeWithRetry(request: ProcessingRequest): Result<ByteArray> {
        var lastException: Exception? = null

        for (attempt in 0 until maxRetries) {
            try {
                val result = applyTransformations(request)
                logProcessingEvent(request, "SUCCESS")
                return Result.success(result)
            } catch (e: Exception) {
                lastException = e
                logRetryEvent(request, attempt, e)
                if (attempt < maxRetries - 1) {
                    Thread.sleep(retryDelays[attempt])
                }
            }
        }

        logProcessingEvent(request, "FAILED")
        return Result.failure(lastException ?: RuntimeException("Unknown error"))
    }

    private fun applyTransformations(request: ProcessingRequest): ByteArray {
        val imageFile = resolveImagePath(request.imageId)
        if (!imageFile.exists()) {
            throw ImageNotFoundException("Image not found: ${request.imageId}")
        }

        var imageData = imageFile.readBytes()

        for (transform in request.transformations) {
            imageData = applyTransform(imageData, transform, request.metadata)
        }

        return imageData
    }

    private fun applyTransform(
        data: ByteArray,
        transform: String,
        metadata: Map<String, String>
    ): ByteArray {
        val description = metadata.getOrDefault("description", "no description")
        val quality = metadata.getOrDefault("quality", "85")

        when (transform) {
            "resize" -> {
                val dimensions = metadata.getOrDefault("dimensions", "800x600")
                logTransformDetail(transform, description, dimensions)
                return performResize(data, dimensions)
            }
            "compress" -> {
                logTransformDetail(transform, description, quality)
                return performCompress(data, quality.toInt())
            }
            "watermark" -> {
                val text = metadata.getOrDefault("watermark_text", "")
                logTransformDetail(transform, description, text)
                return performWatermark(data, text)
            }
            else -> throw UnsupportedTransformException("Unknown transform: $transform")
        }
    }

    private fun logTransformDetail(transform: String, description: String, param: String) {
        val formatStr = "Transform [%s] applied - desc: %s, param: %s"
        val message = String.format(formatStr, transform, description, param)
        logger.info(message)
    }

    private fun logProcessingEvent(request: ProcessingRequest, status: String) {
        val userAgent = request.metadata.getOrDefault("user_agent", "unknown")
        val formatStr = "Processing event - image: %s, user: %s, status: %s, agent: %s"
        val message = String.format(formatStr, request.imageId, request.userId, status, userAgent)
        logger.info(message)
    }

    private fun logRetryEvent(request: ProcessingRequest, attempt: Int, error: Exception) {
        val context = request.metadata.getOrDefault("context", "none")
        val formatStr = "Retry attempt %d for image %s - context: %s, error: %s"
        val message = String.format(formatStr, attempt, request.imageId, context, error.message)
        logger.warning(message)
    }

    private fun resolveImagePath(imageId: String): File {
        val sanitizedId = imageId.replace(Regex("[^a-zA-Z0-9_-]"), "")
        return File("/data/images/$sanitizedId")
    }

    private fun performResize(data: ByteArray, dimensions: String): ByteArray {
        // Simulated resize - in production would use actual image library
        return data
    }

    private fun performCompress(data: ByteArray, quality: Int): ByteArray {
        // Simulated compression
        return data
    }

    private fun performWatermark(data: ByteArray, text: String): ByteArray {
        // Simulated watermark
        return data
    }
}

class RateLimitException(message: String) : Exception(message)
class ImageNotFoundException(message: String) : Exception(message)
class UnsupportedTransformException(message: String) : Exception(message)

fun handleIncomingRequest(params: Map<String, String>): String {
    val pipeline = ImageProcessingPipeline()
    val request = ProcessingRequest(
        imageId = params.getOrDefault("image_id", ""),
        userId = params.getOrDefault("user_id", ""),
        transformations = params.getOrDefault("transforms", "").split(","),
        metadata = params
    )

    val result = pipeline.processImage(request)
    return if (result.isSuccess) {
        String.format("Processed successfully: %d bytes", result.getOrNull()?.size ?: 0)
    } else {
        val errorMsg = result.exceptionOrNull()?.message ?: "unknown error"
        String.format("%s", errorMsg)
    }
}
